interface State { void handle(Context c); }
class Context { State state; void request(){ state.handle(this); } }
class Open implements State { public void handle(Context c){ c.state = new Closed(); } }
class Closed implements State { public void handle(Context c){ c.state = new Open(); } }

class PaymentAdapter {
  constructor(gateway) { this.gateway = gateway; }
  charge(amount) { return this.gateway.pay({ cents: amount * 100 }); }
}

interface Node { int size(); }
class File implements Node { public int size(){ return 1; } }
class Folder implements Node {
  List<Node> children;
  public int size(){ return 1 + children.stream().mapToInt(Node::size).sum(); }
}

def handle(req):
    for h in handlers:
        if h.can_handle(req):
            return h.handle(req)
    raise ValueError('unhandled')

